import{_ as t,C as r,o as i,c as o,E as n,a2 as s}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Creation Provenance Should Survive Resume","description":"","frontmatter":{"title":"Creation Provenance Should Survive Resume","date":"2026-08-23","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"For durable agent work that can be created, forked and resumed, which provenance properties should remain stable across continuation, and which lifecycle transitions may establish a new local provenance identity?","summary":"Creation source and derivation lineage answer different questions. A durable thread should preserve its origin across resume, while a fork may adopt a new local classification; neither field should be mistaken for authenticated authority.","sources":["research/analysis/Q-20260823-02-creation-provenance-continuity.md"],"item_id":"Q-20260823-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-23-creation-provenance-survives-resume-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-08-23-creation-provenance-survives-resume.md","filePath":"en/industry/2026-08-23-creation-provenance-survives-resume.md","lastUpdated":1787666502000}'),c={name:"en/industry/2026-08-23-creation-provenance-survives-resume.md"};function d(l,e,u,h,p,v){const a=r("ArticleCover");return i(),o("div",null,[n(a,{image:"/assets/covers/daily-2026-08-23-creation-provenance-survives-resume-cover-v2.png",kicker:"Industry Architecture · Daily Research",title:"Creation Provenance Should Survive Resume",summary:"Creation source and derivation lineage answer different questions. A durable thread should preserve its origin across resume, while a fork may adopt a new local classification; neither field should be mistaken for authenticated authority.",version:"Q-20260823-02",status:"Daily Runtime V5 · 2026-08-23",languageHref:"/zh/industry/2026-08-23-creation-provenance-survives-resume",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="creation-provenance-should-survive-resume" tabindex="-1">Creation Provenance Should Survive Resume <a class="header-anchor" href="#creation-provenance-should-survive-resume" aria-label="Permalink to &quot;Creation Provenance Should Survive Resume&quot;">​</a></h1><p>If a thread was created by an automated review feature last week, does it become “user work” because a different client resumes it today? If a fork starts a new specialized job, must it pretend to have the same local role as its parent? These are not naming details. They determine whether a durable execution history remains interpretable after repeated lifecycle transitions.</p><p>A Codex change merged on 2026-08-23 makes one design explicit. New exec threads persist a source classification. A fork can carry its own source while retaining parent lineage. The inspected TypeScript resume path deliberately does not forward a new <code>threadSource</code> when a <code>threadId</code> already exists. Together, those behaviors support a two-axis model: <strong>creation source should remain stable through continuation, while derivation is recorded separately from the new object&#39;s local classification.</strong></p><p>The result improves provenance, not authorization. The source can be an application-selected string, so persistence does not authenticate whoever or whatever supplied it.</p><h2 id="resume-should-not-relabel-origin" tabindex="-1">Resume should not relabel origin <a class="header-anchor" href="#resume-should-not-relabel-origin" aria-label="Permalink to &quot;Resume should not relabel origin&quot;">​</a></h2><p>Resume re-enters an existing durable work identity. If every caller can replace the source from its current defaults, provenance becomes a report about the latest invocation rather than the object&#39;s creation event. The same thread could appear to change origin whenever a new SDK, feature or operator continues it.</p><p>The Codex protocol represents <code>User</code>, <code>Subagent</code>, <code>Feature(String)</code> and <code>MemoryConsolidation</code>. A new exec thread receives the chosen classification, defaulting to <code>User</code> when none is provided. In the TypeScript SDK, however, the source flag is added only when no existing thread ID is present. A regression passes a deliberately conflicting value during resume and verifies that it is not forwarded.</p><p>This is a continuation invariant at one documented handoff. It does not establish absolute immutability across every lower-level app-server route. Still, it locates the right default: continuing an object should not rewrite how the object began.</p><p>Operationally, durable systems should declare which metadata belongs to creation and which may change during continuation. A field with no lifecycle scope is eventually governed by whichever caller writes last.</p><h2 id="fork-creates-a-second-provenance-axis" tabindex="-1">Fork creates a second provenance axis <a class="header-anchor" href="#fork-creates-a-second-provenance-axis" aria-label="Permalink to &quot;Fork creates a second provenance axis&quot;">​</a></h2><p>Fork is not resume. It creates a new durable object derived from an existing one. The merged tests show a source thread with one classification and a fork with another, while <code>forked_from_id</code> and history-base metadata retain the parent relationship.</p><p>That separation avoids forcing two questions into one label:</p><ul><li>What local role or producer created this object?</li><li>From which earlier object and history was it derived?</li></ul><p>A fork used for an automated review can truthfully identify that local purpose even when its parent began as user work. Parent lineage preserves the derivation. Copying only the parent&#39;s source would hide the fork&#39;s role; replacing lineage with the new source would hide its ancestry.</p><p>This pattern generalizes to durable jobs, agent sessions and replayable workflows. Continuation-stable metadata and derivation metadata should be modeled as different facts, with explicit transitions for creation, resume, fork and any later governed repair.</p><h2 id="a-durable-label-still-needs-a-trust-binding" tabindex="-1">A durable label still needs a trust binding <a class="header-anchor" href="#a-durable-label-still-needs-a-trust-binding" aria-label="Permalink to &quot;A durable label still needs a trust binding&quot;">​</a></h2><p>Codex accepts arbitrary non-reserved strings as <code>Feature(String)</code>. That openness is useful for product provenance, but it means the label is application-controlled. A caller allowed to create a thread can select a feature name; the field does not prove that the caller is that feature, that a human approved it or that a policy grants it special access.</p><p>Security-sensitive decisions therefore need another binding: an authenticated principal, an attested producer, a policy decision or a signed event that states how much trust the provenance deserves. Source classification can help select records, reconstruct history and route telemetry. It should remain informational until that independent evidence exists.</p><p>The same separation applies to persistence. A label surviving resume is not an immutable audit ledger. Retention, tamper resistance and governed correction require explicit mechanisms. Durability answers whether the value remains available, not whether the value was truthful or authorized.</p><h2 id="compatibility-defaults-are-interpretations" tabindex="-1">Compatibility defaults are interpretations <a class="header-anchor" href="#compatibility-defaults-are-interpretations" aria-label="Permalink to &quot;Compatibility defaults are interpretations&quot;">​</a></h2><p>Missing historical source is interpreted as <code>User</code> for backward compatibility. That is practical for code paths expecting a value, but it is not direct evidence that a user created every historical thread. Analytics or audit systems should be able to distinguish “recorded as User at creation” from “source absent, interpreted as User by compatibility policy.”</p><p>Correction needs the same discipline. An administrator may legitimately repair a wrong creation label, but overwriting it without recording who changed what and why destroys the evidence needed to evaluate the correction. A repairable field can still be continuation-stable if repair is an explicit governed transition rather than ordinary resume behavior.</p><p>The architecture test is concise: for every durable metadata field, specify whether it is creation-scoped, continuation-stable, derivation-scoped or administratively repairable. Then state the trust evidence required before that field participates in authorization. Without those declarations, provenance will drift toward convenience, and convenience will eventually be mistaken for authority.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/openai/codex/commit/a73485dc76e5b2d31d28109a57f6876f4e1dcc24" target="_blank" rel="noreferrer">OpenAI Codex merged commit a73485dc</a>. The code and tests support the scoped create, fork and TypeScript resume behavior described here; they do not independently validate a universal provenance or authorization model.</p>',24))])}const f=t(c,[["render",d]]);export{b as __pageData,f as default};
